SELECT CASE WHEN stores.sqft >= 17067 THEN 'high' WHEN stores.sqft >= 3202 THEN 'mid' ELSE 'low' END AS sqft_bucket, stores.region, MIN(orders.order_date) AS min_order_date, SUM(CASE WHEN orders.status = 'SHIPPED' THEN orders.shipping_fee ELSE 0 END) AS shipped_shipping_fee FROM orders JOIN stores ON orders.store_id = stores.id WHERE orders.shipping_fee >= 39 GROUP BY CASE WHEN stores.sqft >= 17067 THEN 'high' WHEN stores.sqft >= 3202 THEN 'mid' ELSE 'low' END, stores.region HAVING shipped_shipping_fee > 75 ORDER BY 4 DESC, region, sqft_bucket LIMIT 5
